    if not p:
        return "0"
    parts = []
    for k in sorted(p, key=lambda t: (len(t), t)):
        c = p[k]
        if not k:
            parts.append(str(c))
        elif c == 1:
            parts.append("*".join(k))
        elif c == -1:
            parts.append("-" + "*".join(k))
        else:
            parts.append(f"{c}*" + "*".join(k))
    return " + ".join(parts)


